(function() {
    'use strict';

    class LatamExpansionAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'International Market Entry: LATAM Expansion';
            this.version = '1.1.0';

            this.COUNTRIES = {
                mexico: {
                    name: 'Mexico', flag: '🇲🇽', pop: 130, gdppc: 22000,
                    marketSize: 12400, growth: 0.061, modernTrade: 0.56, ecom: 0.18,
                    tariff: 0.15, regCost: 27500, regTime: 4.5, fxVol: 0.12,
                    cageDist: 0.20, regBody: 'COFEPRIS'
                },
                brazil: {
                    name: 'Brazil', flag: '🇧🇷', pop: 215, gdppc: 17500,
                    marketSize: 34100, growth: 0.078, modernTrade: 0.48, ecom: 0.24,
                    tariff: 0.265, regCost: 55000, regTime: 15, fxVol: 0.18,
                    cageDist: 0.70, regBody: 'ANVISA'
                },
                colombia: {
                    name: 'Colombia', flag: '🇨🇴', pop: 52, gdppc: 17200,
                    marketSize: 5800, growth: 0.084, modernTrade: 0.38, ecom: 0.14,
                    tariff: 0.175, regCost: 14000, regTime: 3, fxVol: 0.20,
                    cageDist: 0.15, regBody: 'INVIMA'
                },
                chile: {
                    name: 'Chile', flag: '🇨🇱', pop: 19, gdppc: 28400,
                    marketSize: 4100, growth: 0.038, modernTrade: 0.74, ecom: 0.31,
                    tariff: 0.06, regCost: 10000, regTime: 2, fxVol: 0.10,
                    cageDist: 0.15, regBody: 'ISP'
                },
                peru: {
                    name: 'Peru', flag: '🇵🇪', pop: 34, gdppc: 14600,
                    marketSize: 3400, growth: 0.091, modernTrade: 0.34, ecom: 0.11,
                    tariff: 0.11, regCost: 12000, regTime: 3, fxVol: 0.08,
                    cageDist: 0.10, regBody: 'DIGEMID'
                },
                argentina: {
                    name: 'Argentina', flag: '🇦🇷', pop: 46, gdppc: 24700,
                    marketSize: 9200, growth: 0.021, modernTrade: 0.45, ecom: 0.22,
                    tariff: 0.35, regCost: 21000, regTime: 6, fxVol: 0.40,
                    cageDist: 0.35, regBody: 'ANMAT'
                }
            };

            this.ENTRY_MODES = {
                export: { label: 'Export via Agent', cost: 200000, control: 0.30, timeToRev: 0.5, reversibility: 0.9 },
                distributor: { label: 'Distributor Agreement', cost: 500000, control: 0.40, timeToRev: 0.5, reversibility: 0.6 },
                jv: { label: 'Joint Venture', cost: 5500000, control: 0.70, timeToRev: 0.9, reversibility: 0.3 },
                contract_mfg: { label: 'Contract Manufacturing', cost: 3500000, control: 0.80, timeToRev: 1.1, reversibility: 0.5 },
                acquisition: { label: 'Acquisition', cost: 25000000, control: 1.0, timeToRev: 0, reversibility: 0.1 },
                greenfield: { label: 'Greenfield Subsidiary', cost: 14000000, control: 1.0, timeToRev: 1.7, reversibility: 0.1 }
            };

            this.EVENTS = {
                mexico: [
                    { id: 'mx_usmca', text: 'USMCA renegotiation creates tariff uncertainty. Export-mode firms face 6-month disruption.', affectsExport: true, revImpact: -0.15, costImpact: 80000 },
                    { id: 'mx_cofepris', text: 'COFEPRIS issues new front-of-pack labeling requirements. Packaging redesign needed.', affectsExport: false, revImpact: 0, costImpact: 120000 },
                    { id: 'mx_distributor_defects', text: 'Exclusive distributor defects to a competitor. Distributor-mode firms face 6-month revenue gap.', affectsDistributor: true, revImpact: -0.25, costImpact: 200000 }
                ],
                brazil: [
                    { id: 'br_anvisa', text: 'ANVISA requests additional testing, delaying 2 SKU approvals by 8 months.', affectsExport: false, revImpact: -0.20, costImpact: 150000 },
                    { id: 'br_real_strengthen', text: 'Brazilian real strengthens 15%, boosting USD revenue value but raising local costs.', affectsExport: false, revImpact: 0.10, costImpact: 50000 },
                    { id: 'br_labor_crisis', text: 'Contract manufacturer faces union action — 3-week production stoppage.', affectsContractMfg: true, revImpact: -0.12, costImpact: 100000 }
                ],
                colombia: [
                    { id: 'co_peso_weak', text: 'Colombian peso weakens 18% due to political uncertainty. Local margins compressed.', affectsExport: false, revImpact: -0.08, costImpact: 60000 },
                    { id: 'co_jv_acquired', text: 'Unilever acquires your JV partner. Teams with weak governance get below-market buyout.', affectsJV: true, revImpact: -0.30, costImpact: 500000 },
                    { id: 'co_meli', text: 'Mercado Libre launches fulfillment services in Colombia. E-commerce sales up 25%.', affectsExport: false, revImpact: 0.12, costImpact: 40000 }
                ],
                chile: [
                    { id: 'cl_fast_reg', text: 'ISP approves products in record 6 weeks. Market entry 3 months ahead of schedule.', affectsExport: false, revImpact: 0.15, costImpact: 0 },
                    { id: 'cl_private_label', text: 'Cencosud private label captures 8% market share in household cleaning.', affectsExport: false, revImpact: -0.12, costImpact: 0 },
                    { id: 'cl_manager_resigns', text: 'Country manager resigns to join competitor, taking key retailer relationships.', affectsExport: false, revImpact: -0.15, costImpact: 80000 }
                ],
                peru: [
                    { id: 'pe_yanbal', text: 'Yanbal launches direct competitor to Catalina Pure at 15% lower price.', affectsExport: false, revImpact: -0.10, costImpact: 0 },
                    { id: 'pe_blockade', text: 'Road blockade in Andean routes disrupts provincial distribution for 6 weeks.', affectsExport: false, revImpact: -0.08, costImpact: 30000 },
                    { id: 'pe_growth', text: 'Peru category growth accelerates to 12% on emerging middle class expansion.', affectsExport: false, revImpact: 0.18, costImpact: 0 }
                ],
                argentina: [
                    { id: 'ar_deval', text: 'Argentine peso devalues 40%. Unhedged local revenues severely impacted.', affectsExport: false, revImpact: -0.35, costImpact: 0 },
                    { id: 'ar_boycott', text: 'Social media campaign advocates buying local brands. Foreign brand perception drops.', affectsExport: false, revImpact: -0.20, costImpact: 0 },
                    { id: 'ar_import_restrict', text: 'New import authorization system (SIM) delays product shipments by 4 months.', affectsExport: true, revImpact: -0.25, costImpact: 100000 }
                ]
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    budget: 45000000,
                    totalRevenue: 0,
                    totalProfit: 0,
                    totalInvested: 0,
                    score: 0,
                    markets: [],
                    marketSelections: [],
                    entryModes: [],
                    budgetAllocs: [],
                    revenueHistory: [],
                    profitHistory: [],
                    yearEvents: [],
                    portfolioActions: [],
                    y2Decisions: [],
                    y3Decisions: [],
                    y4Decisions: [],
                    orgModel: '',
                    brandStrategy: '',
                    digitalInvest: ''
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    year: 1,
                    selectedMarkets: [],
                    entryModes: [],
                    budgetAllocs: []
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            var period = state.currentPeriod || 1;

            if (period === 1) {
                var checked = [];
                var boxes = ['chkMexico','chkBrazil','chkColombia','chkChile','chkPeru','chkArgentina'];
                var vals = ['mexico','brazil','colombia','chile','peru','argentina'];
                for (var i = 0; i < boxes.length; i++) {
                    var el = document.getElementById(boxes[i]);
                    if (el && el.checked) checked.push(vals[i]);
                }
                if (checked.length !== 3) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_select_3'), 'warning'
                    );
                    return false;
                }
                decisions.selectedMarkets = checked;

                var modes = [];
                for (var m = 1; m <= 3; m++) {
                    var sel = document.getElementById('entryMode' + m);
                    if (sel) modes.push(sel.value);
                }
                decisions.entryModes = modes;

                var allocs = [];
                var total = 0;
                for (var a = 1; a <= 3; a++) {
                    var inp = document.getElementById('budgetAlloc' + a);
                    var val = inp ? parseInt(inp.value) : 33;
                    allocs.push(val);
                    total += val;
                }
                if (total < 95 || total > 105) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_alloc_100'), 'warning'
                    );
                    return false;
                }
                decisions.budgetAllocs = allocs;

                var totalCost = 0;
                for (var c = 0; c < 3; c++) {
                    var em = this.ENTRY_MODES[modes[c]];
                    totalCost += em ? em.cost : 0;
                }
                if (totalCost > state.domainState.budget) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_budget_exceeded'), 'warning'
                    );
                    return false;
                }

            } else if (period === 2) {
                var y2decs = [];
                for (var mi = 0; mi < 3; mi++) {
                    var distSel = document.getElementById('y2dist_' + mi);
                    var adaptSel = document.getElementById('y2adapt_' + mi);
                    var mktgSel = document.getElementById('y2mktg_' + mi);
                    y2decs.push({
                        distribution: distSel ? distSel.value : 'balanced',
                        adaptation: adaptSel ? adaptSel.value : 'basic',
                        marketing: mktgSel ? mktgSel.value : 'hybrid'
                    });
                }
                decisions.y2Decisions = y2decs;

            } else if (period === 3) {
                var y3decs = [];
                for (var pi = 0; pi < 3; pi++) {
                    var actSel = document.getElementById('y3action_' + pi);
                    var respSel = document.getElementById('y3response_' + pi);
                    y3decs.push({
                        action: actSel ? actSel.value : 'maintain',
                        response: respSel ? respSel.value : 'differentiate'
                    });
                }
                decisions.y3Decisions = y3decs;
                var orgSel = document.getElementById('orgModel');
                decisions.orgModel = orgSel ? orgSel.value : 'market_by_market';

            } else if (period === 4) {
                var bsSel = document.getElementById('brandStrategy');
                var diSel = document.getElementById('digitalInvest');
                decisions.brandStrategy = bsSel ? bsSel.value : 'unified';
                decisions.digitalInvest = diSel ? diSel.value : 'medium';
                var y4decs = [];
                for (var gi = 0; gi < 3; gi++) {
                    var growSel = document.getElementById('y4grow_' + gi);
                    y4decs.push({
                        growthFocus: growSel ? growSel.value : 'steady'
                    });
                }
                decisions.y4Decisions = y4decs;
            }

            decisions.year = period;
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var yearRevenue = 0;
            var yearCosts = 0;
            var yearEvents = [];

            if (period === 1) {
                ds.marketSelections = d.selectedMarkets.slice();
                ds.entryModes = d.entryModes.slice();
                ds.budgetAllocs = d.budgetAllocs.slice();

                var markets = [];
                var totalEntryCost = 0;
                for (var i = 0; i < 3; i++) {
                    var countryKey = d.selectedMarkets[i];
                    var country = this.COUNTRIES[countryKey];
                    var mode = this.ENTRY_MODES[d.entryModes[i]];
                    var allocPct = d.budgetAllocs[i] / 100;
                    var marketBudget = ds.budget * allocPct;
                    var entryCost = mode.cost;
                    totalEntryCost += entryCost;

                    var regCost = country.regCost * 4;
                    var y1MarketingBudget = Math.max(0, (marketBudget - entryCost - regCost) * 0.3);
                    var y1Spend = entryCost + regCost + y1MarketingBudget;
                    // Budget allocated to a market funds first-year marketing, which now gives a
                    // bounded demand boost — so the Year-1 allocation decision has real impact.
                    var y1MktgIntensity = Math.min(0.30, y1MarketingBudget / 4000000);

                    var lofPenalty = 0.60 + (country.cageDist * 0.25);
                    var timeDelay = mode.timeToRev;
                    var revMonths = Math.max(0, 12 - (timeDelay * 12));
                    var baseTargetShare = 0.005;
                    var controlBonus = mode.control * 0.003;
                    var targetShare = baseTargetShare + controlBonus;
                    var revenue = country.marketSize * 1000000 * targetShare * (revMonths / 12) * (1 - lofPenalty) * (1 - country.tariff * 0.3) * (1 + y1MktgIntensity);
                    var operatingCosts = revenue * 0.65;
                    var profit = revenue - operatingCosts - y1Spend;

                    var dci = 0.10 + (mode.control * 0.15);

                    var mkt = {
                        country: countryKey,
                        name: country.name,
                        flag: country.flag,
                        entryMode: d.entryModes[i],
                        modeName: mode.label,
                        allocated: marketBudget,
                        spent: y1Spend,
                        revenue: Math.round(revenue),
                        profit: Math.round(profit),
                        marketShare: Math.round(targetShare * 10000) / 100,
                        dci: Math.round(dci * 100),
                        adaptation: 0,
                        brandEquity: 5 + Math.round(y1MarketingBudget / 100000),
                        lofPenalty: Math.round(lofPenalty * 100),
                        regStatus: timeDelay > 1 ? 'Pending' : 'Approved',
                        cumRevenue: Math.round(revenue),
                        cumProfit: Math.round(profit)
                    };
                    markets.push(mkt);
                    yearRevenue += revenue;
                    yearCosts += y1Spend + operatingCosts;
                }
                ds.markets = markets;
                ds.totalInvested += totalEntryCost;

            } else if (period === 2) {
                ds.y2Decisions = d.y2Decisions ? d.y2Decisions.slice() : [];
                var y2TotalSpend = 0;

                for (var mi = 0; mi < 3; mi++) {
                    var mkt = ds.markets[mi];
                    var country = this.COUNTRIES[mkt.country];
                    var dec = d.y2Decisions && d.y2Decisions[mi] ? d.y2Decisions[mi] : { distribution: 'balanced', adaptation: 'basic', marketing: 'hybrid' };

                    var distCost = { modern_trade: 800000, traditional: 600000, ecommerce: 400000, balanced: 700000 };
                    var adaptCost = { none: 0, basic: 200000, full: 500000 };
                    var mktgCost = { digital: 300000, traditional: 500000, hybrid: 400000, minimal: 100000 };

                    var spend = (distCost[dec.distribution] || 700000) + (adaptCost[dec.adaptation] || 200000) + (mktgCost[dec.marketing] || 400000);
                    y2TotalSpend += spend;

                    var dciGain = { modern_trade: 0.20, traditional: 0.25, ecommerce: 0.12, balanced: 0.18 };
                    mkt.dci = Math.min(85, mkt.dci + Math.round((dciGain[dec.distribution] || 0.18) * 100));

                    var adaptMult = { none: 1.0, basic: 1.12, full: 1.28 };
                    mkt.adaptation = dec.adaptation === 'full' ? 2 : (dec.adaptation === 'basic' ? 1 : 0);

                    var mktgMult = { digital: 1.15, traditional: 1.10, hybrid: 1.12, minimal: 1.02 };
                    var brandGain = { digital: 8, traditional: 6, hybrid: 7, minimal: 2 };
                    mkt.brandEquity += brandGain[dec.marketing] || 5;

                    mkt.lofPenalty = Math.max(10, mkt.lofPenalty - 15 - (mkt.adaptation * 5));
                    mkt.regStatus = 'Approved';

                    var lof = mkt.lofPenalty / 100;
                    var targetShare = mkt.marketShare / 100 + 0.008 + (this.ENTRY_MODES[mkt.entryMode].control * 0.005);
                    var revenue = country.marketSize * 1000000 * targetShare * (1 - lof) * (adaptMult[dec.adaptation] || 1.0) * (mktgMult[dec.marketing] || 1.0) * (1 + Math.min(0.20, mkt.brandEquity / 300)) * (mkt.dci / 100);
                    var opCosts = revenue * 0.58;
                    var profit = revenue - opCosts - spend;

                    mkt.revenue = Math.round(revenue);
                    mkt.profit = Math.round(profit);
                    mkt.marketShare = Math.round(targetShare * 10000) / 100;
                    mkt.cumRevenue += Math.round(revenue);
                    mkt.cumProfit += Math.round(profit);
                    mkt.spent += spend;

                    yearRevenue += revenue;
                    yearCosts += spend + opCosts;
                }
                ds.totalInvested += y2TotalSpend;

                for (var ei = 0; ei < ds.markets.length; ei++) {
                    var evts = this.EVENTS[ds.markets[ei].country];
                    if (evts && evts.length > 0) {
                        var rIdx = Math.floor(Math.random() * evts.length);
                        var evt = evts[rIdx];
                        var revAdj = evt.revImpact * ds.markets[ei].revenue;
                        ds.markets[ei].revenue = Math.round(ds.markets[ei].revenue + revAdj);
                        ds.markets[ei].cumRevenue += Math.round(revAdj);
                        yearRevenue += revAdj;
                        if (evt.costImpact > 0) {
                            ds.markets[ei].spent += evt.costImpact;
                            yearCosts += evt.costImpact;
                            ds.totalInvested += evt.costImpact;
                        }
                        yearEvents.push({ c: ds.markets[ei].country, e: evt.id });
                    }
                }

            } else if (period === 3) {
                ds.y3Decisions = d.y3Decisions ? d.y3Decisions.slice() : [];
                ds.orgModel = d.orgModel || 'market_by_market';
                var orgCost = { regional_hub: 2000000, market_by_market: 800000, outsource: 1200000 };
                var orgMult = { regional_hub: 1.12, market_by_market: 1.0, outsource: 1.05 };
                var y3OrgCost = orgCost[ds.orgModel] || 800000;
                var y3TotalSpend = y3OrgCost;

                for (var mi3 = 0; mi3 < 3; mi3++) {
                    var mkt = ds.markets[mi3];
                    var country = this.COUNTRIES[mkt.country];
                    var dec = d.y3Decisions && d.y3Decisions[mi3] ? d.y3Decisions[mi3] : { action: 'maintain', response: 'differentiate' };
                    ds.portfolioActions.push(dec.action);

                    var actionCost = { double_down: 1500000, maintain: 400000, exit: 500000 };
                    var actionRevMult = { double_down: 1.35, maintain: 1.10, exit: 0 };
                    var respMult = { price_defense: 0.92, differentiate: 1.08, channel_shift: 1.05, retreat: 0.85 };

                    var spend = (actionCost[dec.action] || 400000);
                    y3TotalSpend += spend;

                    if (dec.action === 'exit') {
                        mkt.revenue = 0;
                        mkt.profit = -500000;
                        mkt.marketShare = 0;
                        mkt.dci = 0;
                        yearCosts += 500000;
                        mkt.cumProfit -= 500000;
                    } else {
                        mkt.lofPenalty = Math.max(5, mkt.lofPenalty - 10);
                        mkt.brandEquity += (dec.action === 'double_down' ? 12 : 5);
                        mkt.dci = Math.min(90, mkt.dci + (dec.action === 'double_down' ? 12 : 5));

                        var lof = mkt.lofPenalty / 100;
                        var shareGrowth = 0.006 * (actionRevMult[dec.action] || 1.0);
                        var targetShare = mkt.marketShare / 100 + shareGrowth;
                        var adaptMult2 = 1.0 + (mkt.adaptation * 0.08);
                        var revenue = country.marketSize * 1000000 * targetShare * (1 - lof) * adaptMult2 * (respMult[dec.response] || 1.0) * (orgMult[ds.orgModel] || 1.0) * (1 + Math.min(0.20, mkt.brandEquity / 300)) * (mkt.dci / 100);
                        var opCosts = revenue * 0.52;
                        var profit = revenue - opCosts - spend;

                        mkt.revenue = Math.round(revenue);
                        mkt.profit = Math.round(profit);
                        mkt.marketShare = Math.round(targetShare * 10000) / 100;
                        mkt.cumRevenue += Math.round(revenue);
                        mkt.cumProfit += Math.round(profit);
                        mkt.spent += spend;

                        yearRevenue += revenue;
                        yearCosts += spend + opCosts;
                    }
                }
                ds.totalInvested += y3TotalSpend;

                for (var ei3 = 0; ei3 < ds.markets.length; ei3++) {
                    if (ds.markets[ei3].revenue > 0) {
                        var evts3 = this.EVENTS[ds.markets[ei3].country];
                        if (evts3 && evts3.length > 1) {
                            var rIdx3 = Math.floor(Math.random() * evts3.length);
                            var evt3 = evts3[rIdx3];
                            var revAdj3 = evt3.revImpact * ds.markets[ei3].revenue;
                            ds.markets[ei3].revenue = Math.round(ds.markets[ei3].revenue + revAdj3);
                            ds.markets[ei3].cumRevenue += Math.round(revAdj3);
                            yearRevenue += revAdj3;
                            if (evt3.costImpact > 0) {
                                ds.markets[ei3].spent += evt3.costImpact;
                                yearCosts += evt3.costImpact;
                                ds.totalInvested += evt3.costImpact;
                            }
                            yearEvents.push({ c: ds.markets[ei3].country, e: evt3.id });
                        }
                    }
                }

            } else if (period === 4) {
                ds.brandStrategy = d.brandStrategy || 'unified';
                ds.digitalInvest = d.digitalInvest || 'medium';
                ds.y4Decisions = d.y4Decisions || [];

                var brandCost = { unified: 500000, subbrands: 2000000, localized: 1200000 };
                var brandMult = { unified: 1.05, subbrands: 1.18, localized: 1.12 };
                var digiCost = { low: 300000, medium: 1000000, high: 2500000 };
                var digiMult = { low: 1.02, medium: 1.10, high: 1.20 };

                var y4FixedCost = (brandCost[ds.brandStrategy] || 500000) + (digiCost[ds.digitalInvest] || 1000000);
                var y4TotalSpend = y4FixedCost;

                for (var mi4 = 0; mi4 < 3; mi4++) {
                    var mkt = ds.markets[mi4];
                    if (mkt.revenue === 0 && mkt.marketShare === 0) continue;
                    var country = this.COUNTRIES[mkt.country];
                    var dec4 = d.y4Decisions && d.y4Decisions[mi4] ? d.y4Decisions[mi4] : { growthFocus: 'steady' };

                    var growCost = { aggressive: 1200000, steady: 500000, harvest: 100000 };
                    var growMult = { aggressive: 1.30, steady: 1.12, harvest: 0.95 };

                    var spend = growCost[dec4.growthFocus] || 500000;
                    y4TotalSpend += spend;

                    mkt.lofPenalty = Math.max(2, mkt.lofPenalty - 5);
                    mkt.brandEquity += (dec4.growthFocus === 'aggressive' ? 15 : 8);
                    mkt.dci = Math.min(95, mkt.dci + (dec4.growthFocus === 'aggressive' ? 8 : 3));

                    var lof = mkt.lofPenalty / 100;
                    var shareGrowth4 = 0.008 * (growMult[dec4.growthFocus] || 1.0);
                    var targetShare = mkt.marketShare / 100 + shareGrowth4;
                    var adaptMult4 = 1.0 + (mkt.adaptation * 0.10);
                    var ecomBoost = country.ecom * (digiMult[ds.digitalInvest] || 1.0) * 0.15;
                    var revenue = country.marketSize * 1000000 * targetShare * (1 - lof) * adaptMult4 * (brandMult[ds.brandStrategy] || 1.05) * (1 + ecomBoost) * (1 + Math.min(0.20, mkt.brandEquity / 300)) * (mkt.dci / 100);
                    var opCosts = revenue * 0.48;
                    var profit = revenue - opCosts - spend;

                    mkt.revenue = Math.round(revenue);
                    mkt.profit = Math.round(profit);
                    mkt.marketShare = Math.round(targetShare * 10000) / 100;
                    mkt.cumRevenue += Math.round(revenue);
                    mkt.cumProfit += Math.round(profit);
                    mkt.spent += spend;

                    yearRevenue += revenue;
                    yearCosts += spend + opCosts;
                }
                ds.totalInvested += y4TotalSpend;

                for (var ei4 = 0; ei4 < ds.markets.length; ei4++) {
                    if (ds.markets[ei4].revenue > 0) {
                        var evts4 = this.EVENTS[ds.markets[ei4].country];
                        if (evts4 && evts4.length > 0) {
                            var rIdx4 = Math.floor(Math.random() * evts4.length);
                            var evt4 = evts4[rIdx4];
                            if (Math.random() > 0.5) {
                                var revAdj4 = evt4.revImpact * ds.markets[ei4].revenue;
                                ds.markets[ei4].revenue = Math.round(ds.markets[ei4].revenue + revAdj4);
                                ds.markets[ei4].cumRevenue += Math.round(revAdj4);
                                yearRevenue += revAdj4;
                                yearEvents.push({ c: ds.markets[ei4].country, e: evt4.id });
                            }
                        }
                    }
                }
            }

            var yearProfit = Math.round(yearRevenue - yearCosts);
            yearRevenue = Math.round(yearRevenue);

            ds.totalRevenue += yearRevenue;
            ds.totalProfit += yearProfit;
            ds.budget = 45000000 - ds.totalInvested; // war-chest remaining (investment capital); not used in scoring
            ds.revenueHistory.push(yearRevenue);
            ds.profitHistory.push(yearProfit);
            ds.yearEvents = yearEvents;

            var revScore = Math.min(25, (ds.totalRevenue / 2800000000) * 25);
            var profitScore = ds.totalProfit > 0 ? Math.min(20, (ds.totalProfit / 1400000000) * 20) : 0;
            var efficiency = ds.totalInvested > 0 ? Math.min(15, (ds.totalRevenue / ds.totalInvested) * 15) : 0;
            var avgShare = 0;
            var avgDci = 0;
            var activeMkts = 0;
            for (var si = 0; si < ds.markets.length; si++) {
                if (ds.markets[si].marketShare > 0) {
                    avgShare += ds.markets[si].marketShare;
                    avgDci += ds.markets[si].dci;
                    activeMkts++;
                }
            }
            if (activeMkts > 0) {
                avgShare /= activeMkts;
                avgDci /= activeMkts;
            }
            var shareScore = Math.min(8, (avgShare / 5) * 8);
            var dciScore = Math.min(7, (avgDci / 55) * 7);
            var cageScore = 0;
            for (var ci = 0; ci < ds.marketSelections.length; ci++) {
                var ck = ds.marketSelections[ci];
                if (this.COUNTRIES[ck]) {
                    cageScore += (1 - this.COUNTRIES[ck].cageDist) * 3.33;
                }
            }
            cageScore = Math.min(10, cageScore);
            var oliScore = 0;
            for (var oi = 0; oi < ds.entryModes.length; oi++) {
                var em = this.ENTRY_MODES[ds.entryModes[oi]];
                if (em) oliScore += em.control * 3.33;
            }
            oliScore = Math.min(10, oliScore);
            var resilience = Math.min(5, activeMkts * 1.67);

            ds.score = Math.round(revScore + profitScore + efficiency + shareScore + dciScore + cageScore + oliScore + resilience);

            var self = this;
            // Only mutate the live UI for the real game state. The framework runs
            // calculateResults() on a deep-cloned state for live previews; this guard
            // stops those preview runs from overwriting the on-screen briefing/portfolio.
            var isLiveState = (typeof window !== 'undefined' && window.mySimulation && state === window.mySimulation.state);
            if (isLiveState) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: (state.currentPeriod || 1) + 1 });
                    self._renderPortfolio(ds);
                }, 500);
            }

            return {
                period: state.currentPeriod,
                year: state.currentPeriod,
                yearRevenue: yearRevenue,
                yearProfit: yearProfit,
                totalRevenue: ds.totalRevenue,
                totalProfit: ds.totalProfit,
                budget: ds.budget,
                score: ds.score,
                events: yearEvents.length,
                avgMarketShare: Math.round(avgShare * 100) / 100,
                avgDCI: Math.round(avgDci)
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('budgetDisplay', 'domainState.budget',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('revenueDisplay', 'domainState.totalRevenue',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('profitDisplay', 'domainState.totalProfit',
                (v) => '$' + Math.round(v).toLocaleString());
            uiManager.bind('scoreDisplay', 'domainState.score');

            var self = this;
            var checkboxes = ['chkMexico','chkBrazil','chkColombia','chkChile','chkPeru','chkArgentina'];
            checkboxes.forEach(function(cbId) {
                var cb = document.getElementById(cbId);
                if (cb) {
                    cb.addEventListener('change', function() {
                        self._onMarketSelectionChange();
                    });
                }
            });

            var allocInputs = ['budgetAlloc1','budgetAlloc2','budgetAlloc3'];
            allocInputs.forEach(function(aid) {
                var el = document.getElementById(aid);
                if (el) {
                    el.addEventListener('input', function() {
                        self._updateAllocTotal();
                    });
                }
            });
        }

        _onMarketSelectionChange() {
            var checked = [];
            var boxes = { chkMexico: 'mexico', chkBrazil: 'brazil', chkColombia: 'colombia', chkChile: 'chile', chkPeru: 'peru', chkArgentina: 'argentina' };
            var keys = Object.keys(boxes);
            for (var i = 0; i < keys.length; i++) {
                var el = document.getElementById(keys[i]);
                if (el && el.checked) checked.push(boxes[keys[i]]);
            }

            var entrySection = document.getElementById('entryModesSection');
            var allocSection = document.getElementById('budgetAllocSection');
            if (checked.length === 3) {
                if (entrySection) entrySection.style.display = 'block';
                if (allocSection) allocSection.style.display = 'block';
                for (var m = 0; m < 3; m++) {
                    var lbl1 = document.getElementById('modeLabel' + (m + 1));
                    var lbl2 = document.getElementById('allocLabel' + (m + 1));
                    var c = this.COUNTRIES[checked[m]];
                    var txt = c ? c.flag + ' ' + c.name : checked[m];
                    if (lbl1) lbl1.textContent = txt;
                    if (lbl2) lbl2.textContent = txt;
                }
            } else {
                if (entrySection) entrySection.style.display = 'none';
                if (allocSection) allocSection.style.display = 'none';
            }

            var allBoxes = document.querySelectorAll('.latam-sim-checkbox-group input[type=checkbox]');
            allBoxes.forEach(function(box) {
                if (!box.checked && checked.length >= 3) {
                    box.disabled = true;
                } else {
                    box.disabled = false;
                }
            });
        }

        _updateAllocTotal() {
            var total = 0;
            for (var i = 1; i <= 3; i++) {
                var el = document.getElementById('budgetAlloc' + i);
                if (el) total += parseInt(el.value) || 0;
            }
            var display = document.getElementById('allocTotal');
            if (display) {
                display.textContent = total;
                display.style.color = (total >= 95 && total <= 105) ? '#27ae60' : '#e74c3c';
            }
        }

        _updateBriefing(state) {
            var period = Math.min((state.currentPeriod || 1), 5);
            var briefEl = document.getElementById('briefingText');
            var ds = window.mySimulation && window.mySimulation.state ? window.mySimulation.state.domainState : null;

            if (briefEl) {
                var idx = Math.min(period - 1, 4);
                briefEl.innerHTML = window.mySimulation.t('brief' + (idx + 1));
            }

            var y1 = document.getElementById('year1Panel');
            var y2 = document.getElementById('year2Panel');
            var y3 = document.getElementById('year3Panel');
            var y4 = document.getElementById('year4Panel');
            if (y1) y1.style.display = period === 1 ? 'block' : 'none';
            if (y2) y2.style.display = period === 2 ? 'block' : 'none';
            if (y3) y3.style.display = period === 3 ? 'block' : 'none';
            if (y4) y4.style.display = period === 4 ? 'block' : 'none';

            var eventPanel = document.getElementById('eventPanel');
            var eventText = document.getElementById('eventText');
            if (ds && ds.yearEvents && ds.yearEvents.length > 0) {
                if (eventPanel) eventPanel.style.display = 'block';
                if (eventText) {
                    var selfEv = this;
                    eventText.innerHTML = ds.yearEvents.map(function(ev){
                        if (ev && typeof ev === 'object' && ev.c) {
                            var cc = selfEv.COUNTRIES[ev.c];
                            return (cc ? cc.flag + ' ' : '') + window.mySimulation.t('country_' + ev.c) + ': ' + window.mySimulation.t('evt_' + ev.e);
                        }
                        return ev;
                    }).join('<br><br>');
                }
            } else {
                if (eventPanel) eventPanel.style.display = 'none';
            }

            if (ds && ds.markets && ds.markets.length > 0 && period > 1) {
                this._buildYearPanels(ds, period);
                this._renderPortfolio(ds);
            }
        }

        _buildYearPanels(ds, period) {
            if (period === 2 || period === 3 || period === 4) {
                var containerId = period === 2 ? 'y2MarketsContainer' : (period === 3 ? 'y3MarketsContainer' : 'y4MarketsContainer');
                var container = document.getElementById(containerId);
                if (!container || container.children.length > 0) return;

                for (var i = 0; i < ds.markets.length; i++) {
                    var mkt = ds.markets[i];
                    if (period >= 3 && mkt.marketShare === 0 && mkt.revenue === 0) continue;
                    var div = document.createElement('div');
                    var panelClass = period === 2 ? 'latam-sim-y2-market' : (period === 3 ? 'latam-sim-y3-market' : 'latam-sim-y4-market');
                    div.className = panelClass;
                    var Tb = window.mySimulation.t.bind(window.mySimulation);
                    var html = '<h5>' + mkt.flag + ' ' + Tb('country_' + mkt.country) + ' (' + Tb('lbl_dci') + ': ' + mkt.dci + '%, ' + Tb('lbl_share') + ': ' + mkt.marketShare + '%)</h5>';

                    if (period === 2) {
                        html += '<div class="latam-sim-field-row"><label>' + Tb('y2_dist_label') + '</label><select id="y2dist_' + i + '" class="form-control"><option value="modern_trade">' + Tb('y2_dist_modern') + '</option><option value="traditional">' + Tb('y2_dist_traditional') + '</option><option value="ecommerce">' + Tb('y2_dist_ecom') + '</option><option value="balanced" selected>' + Tb('y2_dist_balanced') + '</option></select></div>';
                        html += '<div class="latam-sim-field-row"><label>' + Tb('y2_adapt_label') + '</label><select id="y2adapt_' + i + '" class="form-control"><option value="none">' + Tb('y2_adapt_none') + '</option><option value="basic" selected>' + Tb('y2_adapt_basic') + '</option><option value="full">' + Tb('y2_adapt_full') + '</option></select></div>';
                        html += '<div class="latam-sim-field-row"><label>' + Tb('y2_mktg_label') + '</label><select id="y2mktg_' + i + '" class="form-control"><option value="digital">' + Tb('y2_mktg_digital') + '</option><option value="traditional">' + Tb('y2_mktg_traditional') + '</option><option value="hybrid" selected>' + Tb('y2_mktg_hybrid') + '</option><option value="minimal">' + Tb('y2_mktg_minimal') + '</option></select></div>';
                    } else if (period === 3) {
                        html += '<div class="latam-sim-field-row"><label>' + Tb('y3_action_label') + '</label><select id="y3action_' + i + '" class="form-control"><option value="double_down">' + Tb('y3_action_double') + '</option><option value="maintain" selected>' + Tb('y3_action_maintain') + '</option><option value="exit">' + Tb('y3_action_exit') + '</option></select></div>';
                        html += '<div class="latam-sim-field-row"><label>' + Tb('y3_resp_label') + '</label><select id="y3response_' + i + '" class="form-control"><option value="price_defense">' + Tb('y3_resp_price') + '</option><option value="differentiate" selected>' + Tb('y3_resp_diff') + '</option><option value="channel_shift">' + Tb('y3_resp_channel') + '</option><option value="retreat">' + Tb('y3_resp_retreat') + '</option></select></div>';
                    } else if (period === 4) {
                        html += '<div class="latam-sim-field-row"><label>' + Tb('y4_grow_label') + '</label><select id="y4grow_' + i + '" class="form-control"><option value="aggressive">' + Tb('y4_grow_aggressive') + '</option><option value="steady" selected>' + Tb('y4_grow_steady') + '</option><option value="harvest">' + Tb('y4_grow_harvest') + '</option></select></div>';
                    }
                    div.innerHTML = html;
                    container.appendChild(div);
                }
            }
        }

        _renderPortfolio(ds) {
            var panel = document.getElementById('portfolioPanel');
            var container = document.getElementById('marketCardsContainer');
            if (!panel || !container || !ds.markets || ds.markets.length === 0) return;

            panel.style.display = 'block';
            container.innerHTML = '';

            for (var i = 0; i < ds.markets.length; i++) {
                var mkt = ds.markets[i];
                var card = document.createElement('div');
                card.className = 'latam-sim-mkt-card';
                var Tp = window.mySimulation.t.bind(window.mySimulation);
                card.innerHTML = '<h5>' + mkt.flag + ' ' + Tp('country_' + mkt.country) + '</h5>' +
                    '<div class="latam-sim-mkt-stat"><span>' + Tp('pc_entry_mode') + '</span><span>' + Tp('emname_' + mkt.entryMode) + '</span></div>' +
                    '<div class="latam-sim-mkt-stat"><span>' + Tp('pc_revenue') + '</span><span>$' + mkt.revenue.toLocaleString() + '</span></div>' +
                    '<div class="latam-sim-mkt-stat"><span>' + Tp('pc_profit') + '</span><span>$' + mkt.profit.toLocaleString() + '</span></div>' +
                    '<div class="latam-sim-mkt-stat"><span>' + Tp('pc_share') + '</span><span>' + mkt.marketShare + '%</span></div>' +
                    '<div class="latam-sim-mkt-stat"><span>' + Tp('pc_dci') + '</span><span>' + mkt.dci + '%</span></div>' +
                    '<div class="latam-sim-mkt-stat"><span>' + Tp('pc_lof') + '</span><span>' + mkt.lofPenalty + '%</span></div>' +
                    '<div class="latam-sim-mkt-stat"><span>' + Tp('pc_brand') + '</span><span>' + mkt.brandEquity + '</span></div>';
                container.appendChild(card);
            }
        }

