                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: (window.mySimulation && window.mySimulation.t ? window.mySimulation.t('chart_revenue') : 'Revenue ($)'),
                                data: [],
                                backgroundColor: 'rgba(39,174,96,0.7)',
                                borderColor: '#27ae60',
                                borderWidth: 2
                            },
                            {
                                label: (window.mySimulation && window.mySimulation.t ? window.mySimulation.t('chart_profit') : 'Profit ($)'),
                                data: [],
                                backgroundColor: 'rgba(142,68,173,0.7)',
                                borderColor: '#8e44ad',
                                borderWidth: 2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: (window.mySimulation && window.mySimulation.t ? window.mySimulation.t('chart_title') : 'Annual Performance') }
