        getChartData(state) {
            var _cy = (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t('chart_year') : 'Year';
            var labels = state.domainState.revenueHistory.map(function(_, i) { return _cy + ' ' + (i + 1); });
            return {
                performanceChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.revenueHistory },
                        { data: state.domainState.profitHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = window.mySimulation.state.domainState;
            var sim = window.mySimulation;
            var totalRev = ds.totalRevenue;
            var totalProfit = ds.totalProfit;
            var revTarget = 500000000;
            var revPct = Math.round((totalRev / revTarget) * 100);
            var breakEven = totalProfit > 0;

            var activeMkts = 0;
            var avgShare = 0;
            var avgDci = 0;
            for (var i = 0; i < ds.markets.length; i++) {
                if (ds.markets[i].marketShare > 0) {
                    avgShare += ds.markets[i].marketShare;
                    avgDci += ds.markets[i].dci;
                    activeMkts++;
                }
            }
            if (activeMkts > 0) {
                avgShare = Math.round(avgShare / activeMkts * 100) / 100;
                avgDci = Math.round(avgDci / activeMkts);
            }

            var performance = sim.t('perf_needs');
            if (ds.score >= 75) performance = sim.t('perf_excellent');
            else if (ds.score >= 55) performance = sim.t('perf_good');
            else if (ds.score >= 35) performance = sim.t('perf_developing');

            var insights = [];
            if (revPct >= 100) {
                insights.push(sim.t('sum_rev_hit'));
            } else {
                insights.push(sim.t('sum_rev_miss').replace('{pct}', revPct));
            }
            if (breakEven) {
                insights.push(sim.t('sum_breakeven_yes'));
            } else {
                insights.push(sim.t('sum_breakeven_no'));
            }
            if (avgShare >= 3) {
                insights.push(sim.t('sum_share_strong').replace('{v}', avgShare));
            } else {
                insights.push(sim.t('sum_share_weak').replace('{v}', avgShare));
            }
            if (avgDci >= 55) {
                insights.push(sim.t('sum_dci_solid').replace('{v}', avgDci));
            } else {
                insights.push(sim.t('sum_dci_weak').replace('{v}', avgDci));
            }

            return {
                totalRevenue: totalRev,
                totalProfit: totalProfit,
                revenueVsTarget: revPct + '%',
                breakEvenAchieved: breakEven,
                avgMarketShare: avgShare + '%',
                avgDCI: avgDci + '%',
                activeMarkets: activeMkts,
                score: ds.score,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var period = state.currentPeriod;
            if (period === 1 && results.yearRevenue < 10000000) {
                return window.mySimulation.t('hint_y1_low');
            }
            if (period === 2 && results.yearProfit < 0) {
                return window.mySimulation.t('hint_y2_loss');
            }
            if (period === 3 && results.totalRevenue < 300000000) {
                return window.mySimulation.t('hint_y3_behind');
            }
            if (period === 4 && results.totalRevenue < 500000000) {
                return window.mySimulation.t('hint_y4_target');
            }
            if (results.events > 0) {
                return window.mySimulation.t('hint_events');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.year', label: 'Year', i18nKey: 'col_year' },
                { key: 'results.yearRevenue', label: 'Revenue', i18nKey: 'col_revenue', formatter: (v) => '$' + Math.round(v).toLocaleString() },
